<?php
/** @var array $categories @var array $items @var array $dishImages @var bool $saved @var \Core\Security\Csrf $csrf @var string $assetBase */
$categoryNames = array_column($categories, 'name', 'id');
?>
<?php if ($saved): ?><div class="flash-ok">Menu changes saved.</div><?php endif; ?>
<div class="card">
<h2 style="margin-top:0">Menu categories</h2>
<table><thead><tr><th>Name</th><th>Slug</th><th>Visible</th><th>Order</th></tr></thead><tbody><?php foreach ($categories as $category): ?><tr><td><?= e($category['name']) ?></td><td><?= e($category['slug']) ?></td><td><?= $category['visible'] ? 'Yes' : 'No' ?></td><td><?= (int) $category['sort_order'] ?></td></tr><?php endforeach; ?></tbody></table>
<form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="add_category"><label>Category name<input name="name" required maxlength="190"></label><label>Description<textarea name="description" rows="3" maxlength="2000"></textarea></label><label>Sort order<input type="number" name="sort_order" value="50"></label><button class="btn" type="submit">Add category</button></form>
</div>
<div class="card">
<h2 style="margin-top:0">Menu items</h2>
<div style="overflow:auto"><table><thead><tr><th>Dish</th><th>Category</th><th>Price</th><th>Dietary</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><div style="display:flex;align-items:center;gap:.75rem"><?php if (!empty($item['image'])): ?><img src="<?= e_attr($assetBase . '/assets/images/menu/' . rawurlencode((string) $item['image'])) ?>" alt="" width="72" height="48" style="width:72px;height:48px;object-fit:cover;border-radius:6px"><?php endif; ?><strong><?= e($item['name']) ?></strong></div></td><td><?= e($categoryNames[$item['category_id']] ?? 'Unknown') ?></td><td>$<?= e(number_format(((int) $item['price_cents']) / 100, 2)) ?></td><td><?= e($item['dietary']) ?></td><td><?= $item['visible'] ? 'Visible' : 'Hidden' ?></td><td><form method="post" style="display:inline"><?= $csrf->field() ?><input type="hidden" name="action" value="toggle_item"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><button class="btn small secondary"><?= $item['visible'] ? 'Hide' : 'Show' ?></button></form> <form method="post" style="display:inline"><?= $csrf->field() ?><input type="hidden" name="action" value="delete_item"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><button class="btn small danger" onclick="return confirm('Remove this menu item?')">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div>
<h3>Add menu item</h3>
<form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="add_item"><label>Category<select name="category_id" required><?php foreach ($categories as $category): ?><option value="<?= (int) $category['id'] ?>"><?= e($category['name']) ?></option><?php endforeach; ?></select></label><label>Name<input name="name" required maxlength="190"></label><label>Description<textarea name="description" rows="3" maxlength="3000"></textarea></label><label>Dish image<select name="image"><option value="">No image</option><?php foreach ($dishImages as $filename => $label): ?><option value="<?= e_attr($filename) ?>"><?= e($label) ?></option><?php endforeach; ?></select></label><label>Price<input type="number" name="price" min="0" step="0.01"></label><label>Price label<input name="price_unit" value="per person" maxlength="80"></label><label>Dietary labels<input name="dietary" placeholder="Vegetarian, Gluten Free" maxlength="255"></label><label><input type="checkbox" name="featured" value="1" style="width:auto"> Feature on homepage</label><label>Sort order<input type="number" name="sort_order" value="50"></label><button class="btn" type="submit">Add menu item</button></form>
</div>
